//! Cargo-driven `hlink.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is hlink-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x740d0000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7ff17000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7ff17000000u64)),
        o => panic!("hlink-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["dll/win32/hlink/hlink_classes_r.o", "body", "engine:uuid", "engine:wine", "engine:c:wine_dll_register", "engine:c:wine_dll_canunload", "engine:oldnames", "import:urlmon", "import:shell32", "import:ole32", "import:advapi32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:delayimp_rust"],
        "x86_64" => &["dll/win32/hlink/hlink_classes_r.o", "body", "engine:uuid", "engine:wine", "engine:c:wine_dll_register", "engine:c:wine_dll_canunload", "engine:oldnames", "import:urlmon", "import:shell32", "import:ole32", "import:advapi32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:delayimp_rust"],
        "aarch64" => &["dll/win32/hlink/hlink_classes_r.o", "body", "engine:uuid", "engine:wine", "engine:c:wine_dll_register", "engine:c:wine_dll_canunload", "engine:oldnames", "import:urlmon", "import:shell32", "import:ole32", "import:advapi32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:delayimp_rust"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("hlink-rust")
        .c_from_compile_db("hlink_shims", &["dll/win32/hlink/rust_cohab_stub.c"])
        .spec2def("dll/win32/hlink/hlink.spec", "hlink.dll")
        .spec_stubs()
        .delay_import_lib("dll/win32/urlmon/urlmon.spec", "urlmon.dll", "urlmon")
        .import_lib("dll/win32/shell32/shell32.spec", "shell32.dll", "shell32")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
